def fill_project_slugs(apps, schema_editor):
    """Existing cases get a placeholder slug; rename them in the admin."""
    Project = apps.get_model("main", "Project")
    for project in Project.objects.filter(slug=""):
        project.slug = f"case-{project.pk}"
        project.save(update_fields=["slug"])


